function saveLocal(){try{localStorage.setItem('museNotes',state.notes);localStorage.setItem('museStrokes',JSON.stringify(state.strokes));localStorage.setItem('museEnriched',JSON.stringify(state.enriched));localStorage.setItem('museMarks',JSON.stringify(state.manualMarks))}catch{toast('本机存储空间不足，请导出笔记。')}}
function openDB(){return new Promise((resolve,reject)=>{const r=indexedDB.open('muse-classroom',1);r.onupgradeneeded=()=>{r.result.createObjectStore('files',{keyPath:'id'});r.result.createObjectStore('sessions',{keyPath:'id'})};r.onsuccess=()=>{db=r.result;resolve(db)};r.onerror=()=>reject(r.error)})}
function dbAll(store){return new Promise((resolve,reject)=>{let r=db.transaction(store).objectStore(store).getAll();r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error)})}
function dbPut(store,value){return new Promise((resolve,reject)=>{let tx=db.transaction(store,'readwrite');tx.objectStore(store).put(value);tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}
