function bindMain(){document.onselectionchange=()=>{};$('#accent').onchange=e=>{state.accent=e.target.value;localStorage.setItem('museAccent',JSON.stringify(state.accent));toast('已保存口音偏好；真实语音识别尚未接入')};$('#waveform').onclick=e=>{if(!activeAudio.src||!Number.isFinite(activeAudio.duration))return;const r=e.currentTarget.getBoundingClientRect();activeAudio.currentTime=Math.max(0,Math.min(1,(e.clientX-r.left)/r.width))*activeAudio.duration;updatePlayer()};$('#waveform').onkeydown=e=>{if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();activeAudio.currentTime=Math.max(0,Math.min(activeAudio.duration||0,activeAudio.currentTime+(e.key==='ArrowRight'?5:-5)));updatePlayer()}}}
function setTab(tab){state.tab=tab;render();if(tab==='transcript')scrollToCurrent()}
function seek(id,play=false){if(state.mode==='real'&&state.recording){toast('请先结束当前录音，再回到示例课堂。');return}if(state.mode!=='demo'){realAudio.pause();state.mode='demo';activeAudio=demoAudio;state.duration=demoAudio.duration||158}const s=getSegment(id);state.current=s.id;state.page=s.page;state.selectedFile=null;state.tab='transcript';if(Number.isFinite(demoAudio.duration))demoAudio.currentTime=s.time;render();scrollToCurrent();if(play)playAudio();toast(`已定位讲解 ${timeLabel(s.time)} · 课件 P.${s.page}`)}
function scrollToCurrent(){requestAnimationFrame(()=>{let el=document.getElementById(state.current),root=$('#contentScroll');if(el&&root)root.scrollTo({top:Math.max(0,el.offsetTop-root.offsetTop-40),behavior:'smooth'})})}
function showTerm(key,anchor){if(state.mode!=='demo'){toast('术语解释当前为示例课堂功能');return}let t=DEMO_TERMS[key],pop=$('#popover');if(!t)return;pop.innerHTML=`<div class="pop-head"><span class="term-en">${t.en}</span><button class="icon-btn" data-action="closePopover" aria-label="关闭解释">×</button></div><h3>${t.zh}</h3><p>${t.description}</p><div class="pop-formula">${t.formula}</div><p><strong>放回这一课：</strong>${t.context}</p><div class="pop-links"><button data-seek="${t.segment}">${icon('play',11)} ${timeLabel(getSegment(t.segment).time)} 回到讲解</button><button data-page="${t.page}">${icon('file',11)} 课件 P.${t.page}</button></div><small>示例解释 · 当前录音持续保留</small>`;pop.hidden=false;let r=anchor.getBoundingClientRect();let x=Math.min(window.innerWidth-pop.offsetWidth-12,Math.max(12,r.left));let y=r.bottom+10;if(y+pop.offsetHeight>window.innerHeight-80)y=Math.max(10,r.top-pop.offsetHeight-10);pop.style.left=x+'px';pop.style.top=y+'px'}
function addFocus(id){let s=getSegment(id);state.notes+=(state.notes?'\n\n':'')+`[${timeLabel(s.time)} · 课件 P.${s.page}] ${s.zh}`;saveLocal();state.noteTab='focus';renderNotes();toast('已记入我的笔记，并保留讲解时间')}
function enrich(){if(state.mode!=='demo'){toast('真实课堂的笔记补充需要接入 AI；示例课堂可体验此功能。');return}state.enriched=true;saveLocal();state.noteTab='focus';renderNotes();toast('已补充硬币例子和适用条件；你的手写内容已保留')}
function askAI(question){question=question.trim();if(!question)return;let thread=$('#aiThread');if(!thread)return;let user=document.createElement('div');user.className='ai-message user';user.textContent=question;thread.appendChild(user);let answer=document.createElement('div');answer.className='ai-message';let key=/聚类|cluster|分类|地图/i.test(question)?'clustering':/分布|probability/i.test(question)?'probability':/熵|entropy|硬币/i.test(question)?'entropy':null;if(state.mode==='real'){answer.innerHTML='<small>服务状态</small>这份真实录音还没有转写结果。当前可以回听、查看课件和手写笔记；示例问答可以在示例课堂体验。'}else if(/笔记|补充|手写/.test(question)){answer.innerHTML=`<small>示例助教 · 预设回答</small>可以根据课堂内容补充“相同结果集合”的前提、公平硬币例子和聚类的距离条件。手写保留为原图，当前不识别笔迹。<br><button class="source-link" data-action="enrich">${icon('spark',11)} 补充到 Focus 笔记</button>`}else if(key){const t=DEMO_TERMS[key];answer.innerHTML=`<small>示例助教 · 预设回答</small><strong>${t.zh} / ${t.en}</strong><br>${t.description}<br>${t.context}<div class="pop-formula" style="margin:8px 0">${t.formula}</div><button class="source-link" data-seek="${t.segment}">${icon('link',11)} ${timeLabel(getSegment(t.segment).time)} 讲解原文</button>　<button class="source-link" data-page="${t.page}">课件 P.${t.page}</button>`}else{answer.innerHTML='<small>示例助教 · 范围提示</small>这个原型只提供信息熵、概率分布、聚类与笔记补充的示例回答。你可以点击下方问题体验来源定位。'}thread.appendChild(answer);thread.scrollTop=thread.scrollHeight}
async function playAudio(){try{if(!activeAudio.src){toast('请先录制或导入音频');return}if(activeAudio.paused){await activeAudio.play()}else activeAudio.pause();updatePlayer()}catch{toast('音频暂时无法播放，请重新加载或导入自己的音频。')}}
function updatePlayer(){let t=activeAudio.currentTime||0,d=Number.isFinite(activeAudio.duration)?activeAudio.duration:state.duration;const btn=$('.play');if(btn)btn.innerHTML=icon(activeAudio.paused?'play':'pause',16);if($('#audioTime'))$('#audioTime').innerHTML=`${timeLabel(t)} <span style="color:#c1c9b7">/</span> ${timeLabel(d)}`;let bars=$$('#waveform i');bars.forEach((b,i)=>b.classList.toggle('played',i/bars.length<=t/(d||1)));$('#waveform')?.setAttribute('aria-valuenow',Math.round(t));$('#waveform')?.setAttribute('aria-valuemax',Math.round(d));if(state.mode==='demo'){let seg=[...DEMO_SEGMENTS].reverse().find(s=>s.time<=t);if(seg&&seg.id!==state.current){state.current=seg.id;$$('.segment').forEach(el=>el.classList.toggle('active',el.id===seg.id))}}}
[demoAudio,realAudio].forEach(a=>{a.addEventListener('timeupdate',updatePlayer);a.addEventListener('ended',updatePlayer);a.addEventListener('pause',updatePlayer);a.addEventListener('play',updatePlayer);a.addEventListener('loadedmetadata',()=>{if(a===activeAudio){state.duration=Number.isFinite(a.duration)?a.duration:(state.realDuration||state.duration);updatePlayer()}})});
function download(blob,name){const url=URL.createObjectURL(blob);let a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000)}
function exportNotes(){let html=`<!doctype html><html lang="zh"><meta charset="UTF-8"><title>demo 课堂笔记</title><body style="max-width:800px;margin:40px auto;font-family:Arial,sans-serif;line-height:1.8"><h1>demo · 课堂笔记</h1><p>${state.mode==='demo'?'统计与信息论 · 示例课堂':'我的课堂录音'}</p><h2>我的 Focus 笔记</h2><p style="white-space:pre-wrap">${esc(state.notes||'分布越均匀，越难预测？\n地图上的点，怎么分组？')}</p>`;if(state.enriched)html+='<h2>示例讲解补充</h2><p>在相同有限结果集合中，均匀分布的熵最大。公平硬币 H=1 bit；确定结果 H=0。</p>';if(state.strokes.length){let c=document.createElement('canvas');c.width=1000;c.height=650;drawStrokes(c,state.strokes);html+=`<h2>手写与草图</h2><img style="width:100%;border:1px solid #ddd" src="${c.toDataURL()}">`}if(state.mode==='demo')html+='<h2>讲解来源</h2>'+DEMO_SEGMENTS.map(s=>`<p><b>${timeLabel(s.time)} · 课件 P.${s.page}</b><br>${esc(s.en)}<br>${esc(s.zh)}</p>`).join('');html+='</body></html>';download(new Blob([html],{type:'text/html;charset=utf-8'}),'demo-课堂笔记.html');toast('笔记与手写图已导出为可阅读的 HTML 文件')}
function drawStrokes(canvas,strokes){let ctx=canvas.getContext('2d');ctx.clearRect(0,0,canvas.width,canvas.height);strokes.forEach(stroke=>{ctx.save();ctx.globalCompositeOperation=stroke.erase?'destination-out':'source-over';ctx.strokeStyle=stroke.color;ctx.lineWidth=(stroke.erase?18:2.3)*(canvas.width/320);ctx.lineCap='round';ctx.lineJoin='round';ctx.beginPath();stroke.points.forEach((p,i)=>{if(i===0)ctx.moveTo(p.x*canvas.width,p.y*canvas.height);else ctx.lineTo(p.x*canvas.width,p.y*canvas.height)});if(stroke.points.length===1){let p=stroke.points[0];ctx.lineTo(p.x*canvas.width+.1,p.y*canvas.height+.1)}ctx.stroke();ctx.restore()})}
function initCanvas(){let c=$('#noteCanvas');if(!c)return;const resize=()=>{if(!c.isConnected)return;let r=c.getBoundingClientRect();c.width=Math.max(1,r.width*devicePixelRatio);c.height=Math.max(1,r.height*devicePixelRatio);drawStrokes(c,state.strokes)};requestAnimationFrame(resize);const ro=new ResizeObserver(resize);ro.observe(c);let stroke=null;const pt=e=>{let r=c.getBoundingClientRect();return{x:(e.clientX-r.left)/r.width,y:(e.clientY-r.top)/r.height}};c.onpointerdown=e=>{e.preventDefault();c.setPointerCapture(e.pointerId);stroke={color:state.pen,erase:state.tool==='eraser',points:[pt(e)]};state.strokes.push(stroke);drawStrokes(c,state.strokes)};c.onpointermove=e=>{if(!stroke)return;e.preventDefault();stroke.points.push(pt(e));drawStrokes(c,state.strokes)};c.onpointerup=c.onpointercancel=()=>{if(stroke){stroke=null;saveLocal();$('.canvas-hint').style.opacity=state.strokes.length?'.35':'1'}}}
async function startRecording(){if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){toast('当前浏览器不支持录音，请使用 Chrome / Edge 的安全页面。');return}$('#recordDialog').close();try{stream=await navigator.mediaDevices.getUserMedia({audio:true,video:false});activeAudio.pause();state.mode='real';activeAudio=realAudio;realAudio.removeAttribute('src');chunks=[];recorder=new MediaRecorder(stream);recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data)};recorder.onstop=async()=>{const blob=new Blob(chunks,{type:recorder.mimeType});stream.getTracks().forEach(t=>t.stop());if(realURL)URL.revokeObjectURL(realURL);realURL=URL.createObjectURL(blob);realAudio.src=realURL;state.audioName='demo-课堂录音.'+(recorder.mimeType.includes('mp4')?'m4a':'webm');const session={id:crypto.randomUUID(),title:'课堂录音 '+new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'}),duration:state.realDuration,blob,created:new Date().toISOString()};state.sessions.push(session);try{if(db)await dbPut('sessions',session)}catch{toast('录音暂未持久保存，请立即下载音频。')}state.duration=state.realDuration;state.tab='summary';render();toast('录音已结束，可回听、下载并继续手写笔记。')};recorder.start(500);state.recording=true;state.realDuration=0;state.tab='transcript';state.duration=0;render();recordTimer=setInterval(()=>{state.realDuration++;$('#audioTime').textContent=timeLabel(state.realDuration)+' · 录音中'},1000)}catch(e){stream?.getTracks().forEach(t=>t.stop());toast(e.name==='NotAllowedError'?'未取得麦克风权限，可重新尝试或导入音频。':'无法开始录音：'+e.message)}}
function stopRecording(){if(recorder&&recorder.state!=='inactive'){state.recording=false;clearInterval(recordTimer);recorder.stop()}}
async function importAudio(file){if(!file)return;if(state.recording){toast('请先结束当前录音');return}activeAudio.pause();if(realURL)URL.revokeObjectURL(realURL);realURL=URL.createObjectURL(file);realAudio.src=realURL;state.mode='real';state.audioName=file.name;activeAudio=realAudio;state.tab='transcript';$('#recordDialog').close();const session={id:crypto.randomUUID(),title:file.name,duration:0,blob:file,created:new Date().toISOString()};try{await new Promise((res,rej)=>{realAudio.onloadedmetadata=res;realAudio.onerror=rej});session.duration=Number.isFinite(realAudio.duration)?realAudio.duration:0;state.duration=session.duration;state.sessions.push(session);if(db)await dbPut('sessions',session);render();toast('录音已导入，可以回放并添加笔记')}catch{render();toast('音频可能无法播放，请尝试 MP3、M4A 或 WAV。')}}
async function parsePPTX(buffer){if(!window.fflate)throw new Error('PPTX 解析组件不可用');const zip=fflate.unzipSync(new Uint8Array(buffer));const slidePaths=Object.keys(zip).filter(k=>/^ppt\/slides\/slide\d+\.xml$/.test(k)).sort((a,b)=>parseInt(a.match(/slide(\d+)/)[1])-parseInt(b.match(/slide(\d+)/)[1]));if(!slidePaths.length)throw new Error('文件中没有可读取的幻灯片');const decoder=new TextDecoder();return slidePaths.map(path=>{const xml=new DOMParser().parseFromString(decoder.decode(zip[path]),'text/xml');const texts=[...xml.getElementsByTagName('a:t')].map(n=>n.textContent);const relPath=path.replace('slides/','slides/_rels/')+'.rels';const images=[];if(zip[relPath]){const rels=new DOMParser().parseFromString(decoder.decode(zip[relPath]),'text/xml');[...rels.getElementsByTagName('Relationship')].filter(n=>(n.getAttribute('Type')||'').endsWith('/image')).slice(0,3).forEach(n=>{let target=n.getAttribute('Target')||'';if(!target.startsWith('../media/'))return;let p='ppt/'+target.slice(3);if(zip[p]&&/\.(png|jpg|jpeg|gif|webp)$/i.test(p)){let bytes=zip[p],s='';for(let i=0;i<bytes.length;i+=8192)s+=String.fromCharCode(...bytes.subarray(i,i+8192));let ext=p.split('.').pop().toLowerCase();images.push(`data:image/${ext==='jpg'?'jpeg':ext};base64,${btoa(s)}`)}})}return{title:texts[0]||'幻灯片',text:texts.slice(1).join('\n'),images}})}
async function uploadFiles(files){for(const file of files){let row=document.createElement('div');row.className='upload-item';row.textContent=file.name+' · 正在处理…';$('#uploadProgress').appendChild(row);try{if(file.size>35*1024*1024)throw new Error('请使用 35MB 以内的课件');let ext=file.name.split('.').pop().toLowerCase();if(!['pdf','pptx'].includes(ext))throw new Error('请上传 PDF 或 PPTX，旧版 PPT 请先另存为 PDF');let data=await file.arrayBuffer(),entry={id:crypto.randomUUID(),name:file.name,type:ext,data};if(ext==='pptx')entry.slides=await parsePPTX(data);if(db)await dbPut('files',entry);state.files.push(entry);row.innerHTML=`<span>${esc(file.name)}</span><span>✓ 已加入课件</span>`;state.selectedFile=entry.id;state.page=1;state.tab='slides';render();}catch(e){row.className='upload-item error';row.textContent=file.name+' · '+e.message}}$('#courseInput').value=''}
document.addEventListener('click',e=>{const target=e.target.closest('button,[data-page],[data-seek],[data-term]');if(!target){if(!e.target.closest('#popover'))$('#popover').hidden=true;return}if(!target.closest('#popover'))$('#popover').hidden=true;if(target.dataset.term){if(target.dataset.term==='clustering'){seek('s5');toast('已回到前面的「聚类」章节，可点击时间回听讲解');}else showTerm(target.dataset.term,target);return}if(target.dataset.seek){$('#popover').hidden=true;seek(target.dataset.seek);return}if(target.dataset.page){state.page=Number(target.dataset.page);state.selectedFile=null;state.tab='slides';render();return}if(target.dataset.file){state.selectedFile=target.dataset.file;state.page=1;state.tab='slides';render();return}if(target.dataset.session){if(state.recording){toast('请先结束当前录音');return}let s=state.sessions.find(s=>s.id===target.dataset.session);if(s){activeAudio.pause();if(realURL)URL.revokeObjectURL(realURL);realURL=URL.createObjectURL(s.blob);realAudio.src=realURL;activeAudio=realAudio;state.mode='real';state.audioName=s.title.startsWith('课堂录音 ')?'demo-课堂录音.'+(s.blob.type.includes('mp4')?'m4a':'webm'):s.title;state.duration=s.duration;state.tab='transcript';render()}return}if(target.dataset.tab){setTab(target.dataset.tab);return}if(target.dataset.noteTab){state.noteTab=target.dataset.noteTab;render();return}if(target.dataset.highlight){state.highlight=target.dataset.highlight;localStorage.setItem('museHighlight',JSON.stringify(state.highlight));render();toast(state.highlight==='manual'?'选中转写文字后，点击弹出的标注；也可在段落右侧标重点。':'已显示示例课堂的 AI 重点标注');return}if(target.dataset.mark){const id=target.dataset.mark;state.manualMarks=state.manualMarks.includes(id)?state.manualMarks.filter(x=>x!==id):[...state.manualMarks,id];saveLocal();renderContent();return}if(target.dataset.focus){addFocus(target.dataset.focus);return}if(target.dataset.tool){state.tool=target.dataset.tool;renderNotes();return}if(target.dataset.color){state.pen=target.dataset.color;state.tool='pen';renderNotes();return}if(target.dataset.prompt){askAI(target.dataset.prompt);return}let action=target.dataset.action;
 switch(action){case'upload':$('#uploadDialog').showModal();break;case'record':if(state.recording)stopRecording();else $('#recordDialog').showModal();break;case'play':playAudio();break;case'back10':activeAudio.currentTime=Math.max(0,activeAudio.currentTime-10);updatePlayer();break;case'speed':{let speeds=[1,1.25,1.5,2,.75];activeAudio.playbackRate=speeds[(speeds.indexOf(activeAudio.playbackRate)+1)%speeds.length];target.textContent=activeAudio.playbackRate+'×';break}case'mute':activeAudio.muted=!activeAudio.muted;toast(activeAudio.muted?'已静音':'已取消静音');break;case'downloadAudio':{if(state.recording){toast('结束录音后即可下载');break}if(state.mode==='demo'){let a=document.createElement('a');a.href='assets/demo-lecture.wav';a.download='demo-合成语音示例.wav';a.click()}else{let s=state.sessions[state.sessions.length-1];if(realURL){let a=document.createElement('a');a.href=realURL;a.download=state.audioName;a.click()}else toast('请先录制或导入音频')}break}case'translation':state.translation=!state.translation;localStorage.setItem('museTranslation',JSON.stringify(state.translation));render();break;case'classroom':if(state.recording){toast('请先结束当前录音');break}activeAudio.pause();state.mode='demo';activeAudio=demoAudio;state.duration=demoAudio.duration||158;state.tab='transcript';state.selectedFile=null;render();scrollToCurrent();break;case'overview':state.tab='overview';render();break;case'openAI':state.noteTab='ai';render();$('#aiInput')?.focus();break;case'demoSlides':state.selectedFile=null;state.page=3;setTab('slides');break;case'prevPage':state.page=Math.max(1,state.page-1);renderContent();break;case'nextPage':{let f=state.files.find(f=>f.id===state.selectedFile);state.page=Math.min(f?.pages||f?.slides?.length||6,state.page+1);renderContent();break}case'enrich':enrich();break;case'export':exportNotes();break;case'closePopover':$('#popover').hidden=true;break;case'undoStroke':state.strokes.pop();saveLocal();if($('#noteCanvas'))drawStrokes($('#noteCanvas'),state.strokes);break;case'expandCanvas':state.expanded=!state.expanded;renderNotes();break;case'sampleSketch':{const group=(cx,cy,color)=>{const points=Array.from({length:45},(_,i)=>{const a=i/44*Math.PI*2;return{x:cx+Math.cos(a)*.15,y:cy+Math.sin(a)*.21}});state.strokes.push({color,erase:false,points});[[0,0],[.06,.05],[-.05,.07],[.03,-.08]].forEach(([dx,dy])=>{state.strokes.push({color,erase:false,points:[{x:cx+dx,y:cy+dy},{x:cx+dx+.004,y:cy+dy+.004}]});});};group(.28,.53,'#48613d');group(.7,.4,'#d39a60');saveLocal();drawStrokes($('#noteCanvas'),state.strokes);toast('已画入示例聚类草图，你可以继续手写补充。');break}case'saveDrawing':{let c=document.createElement('canvas');c.width=1200;c.height=800;drawStrokes(c,state.strokes);c.toBlob(blob=>download(blob,'demo-手写笔记.png'));break}case'regenerate':state.summaryReady=true;localStorage.setItem('museSummary','true');renderContent();toast('示例总结已整理：知识点、课件图片和讲解来源相互关联');break;case'settings':$('#accentSetting').value=state.accent;$('#settingsDialog').showModal();break;}
});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){state.expanded=false;$('#popover').hidden=true;if($('#handwriteCard')?.classList.contains('canvas-expanded'))renderNotes()}});
$$('.close-dialog').forEach(b=>b.onclick=()=>b.closest('dialog').close());$('#micRecord').onclick=startRecording;$('#demoChoice').onclick=()=>{$('#recordDialog').close();state.mode='demo';activeAudio=demoAudio;state.tab='transcript';render();toast('示例课堂已就绪：点击术语、课件或播放音频开始体验')};$('#audioInput').onchange=e=>importAudio(e.target.files[0]);$('#courseInput').onchange=e=>uploadFiles(e.target.files);$('#saveSettings').onclick=()=>{state.accent=$('#accentSetting').value;localStorage.setItem('museAccent',JSON.stringify(state.accent));$('#settingsDialog').close();render();toast('课堂设置已保存')};let drop=$('#dropzone');drop.ondragover=e=>{e.preventDefault();drop.classList.add('dragover')};drop.ondragleave=()=>drop.classList.remove('dragover');drop.ondrop=e=>{e.preventDefault();drop.classList.remove('dragover');uploadFiles(e.dataTransfer.files)};
window.addEventListener('beforeunload',e=>{if(state.recording){e.preventDefault();e.returnValue='录音尚未结束';}});
if(window.pdfjsLib)pdfjsLib.GlobalWorkerOptions.workerSrc='vendor/pdf.worker.min.js';
render();openDB().then(async()=>{state.files=await dbAll('files');state.sessions=await dbAll('sessions');render()}).catch(()=>toast('浏览器持久存储不可用；请及时导出笔记和录音。'));
